import React from 'react'
import './App.css';
import {BrowserRouter as Router, Switch, Route, Redirect} from "react-router-dom";
import professorList from './json/professorsList.json'
//Pages
import Home from './pages/Home.js'
import NotFoundPage from './pages/404'
// import Professor from "./pages/Professor";


function App() {

  const [professor, setProfessor] = "";

  return (
      <Router>
        <Switch>
          <Route path='/' exact component={() => <Home professorList={professorList} onChangeProfessor={setProfessor} />}/>
          <Route path='/404' exact component={NotFoundPage}/>
          {/*<Route path="/professors" exact component={() => <Professor professor={professor} />} />*/}
          <Redirect to="/404"/>
        </Switch>
      </Router>
  );
}

export default App;
